#if UNITY_IOS && !WAGENHEIMER_NATIVESOCIAL_NO_GAMECENTER
using System.IO;

using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEditor.iOS.Xcode;

using UnityEngine;

namespace Wagenheimer.NativeSocial.Editor
{
    /// <summary>
    /// Adds the Game Center capability to the Xcode project generated by the iOS build.
    ///
    /// Unity has no Game Center toggle in the iOS Player Settings and never adds the entitlement on its own. Without
    /// <c>com.apple.developer.game-center</c>, <c>GKLocalPlayer</c> never authenticates, so <c>NativeSocial.Authenticate</c>
    /// fails silently on iOS and any Game Center consumer (achievements, Cloud Save linking) falls back to a local/anonymous account.
    ///
    /// Opt out with the <c>WAGENHEIMER_NATIVESOCIAL_NO_GAMECENTER</c> scripting define if a title deliberately ships without
    /// Game Center on iOS (App Store Connect must also have Game Center enabled for the bundle id).
    ///
    /// This file lives inside the package so every consumer gets the capability without copying a post-process script into
    /// the game project. It is guarded by UNITY_IOS, so it compiles to nothing on Android/desktop targets.
    /// </summary>
    public sealed class GameCenterCapabilityBuildStep : IPostprocessBuildWithReport
    {
        private const string GameCenterEntitlement = "com.apple.developer.game-center";

        public int callbackOrder => 10001;

        public void OnPostprocessBuild(BuildReport report)
        {
            if (report.summary.platform != BuildTarget.iOS) return;

            var projectPath = PBXProject.GetPBXProjectPath(report.summary.outputPath);
            var project = new PBXProject();
            project.ReadFromFile(projectPath);

            var targetGuid = project.GetUnityMainTargetGuid();
            if (string.IsNullOrEmpty(targetGuid))
            {
                Debug.LogWarning("[NativeSocial] Unity-iPhone target not found in the generated Xcode project; the Game Center capability was not added.");
                return;
            }

            // Reuse the entitlements file another capability already points at (Sign in with Apple, push, ...).
            var entitlementsPath = project.GetBuildPropertyForAnyConfig(targetGuid, "CODE_SIGN_ENTITLEMENTS");
            if (string.IsNullOrEmpty(entitlementsPath))
                entitlementsPath = "Unity-iPhone.entitlements";

            var entitlementsFile = Path.Combine(report.summary.outputPath, entitlementsPath);
            if (File.Exists(entitlementsFile) && File.ReadAllText(entitlementsFile).Contains(GameCenterEntitlement))
            {
                Debug.Log("[NativeSocial] Game Center capability already present in " + entitlementsPath + ".");
                return;
            }

            var manager = new ProjectCapabilityManager(projectPath, entitlementsPath, null, targetGuid);
            manager.AddGameCenter();
            manager.WriteToFile();

            Debug.Log($"[NativeSocial] Added the Game Center capability to the generated Xcode project (entitlements: {entitlementsPath}).");
        }
    }
}
#endif
